xpath.script:
//
document.addEventListener("DOMContentLoaded", function () { var descDiv = document.querySelector(".oe_no_empty.pb-2.text-break"); if (!descDiv) return; var imgs = descDiv.querySelectorAll("img"); if (imgs.length < 2) return; /* Build slider only when there are 2+ images */ var sliderWrap = document.createElement("div"); sliderWrap.style.cssText = "position:relative; width:100%; overflow:hidden; border-radius:12px; margin-top:12px;"; var track = document.createElement("div"); track.style.cssText = "display:flex; transition:transform 0.4s ease; will-change:transform;"; imgs.forEach(function (img) { var slide = document.createElement("div"); slide.style.cssText = "flex:0 0 100%; display:flex; align-items:center; justify-content:center; background:#f8f9ff; border-radius:12px; overflow:hidden; max-height:340px;"; var cloned = img.cloneNode(true); cloned.style.cssText = "max-width:100%; max-height:340px; object-fit:contain;"; slide.appendChild(cloned); track.appendChild(slide); img.parentNode.removeChild(img); }); sliderWrap.appendChild(track); /* Dots */ var dotsWrap = document.createElement("div"); dotsWrap.style.cssText = "display:flex; justify-content:center; gap:6px; margin-top:10px;"; var dots = []; var current = 0; function goTo(n) { current = (n + imgs.length) % imgs.length; track.style.transform = "translateX(-" + (current * 100) + "%)"; dots.forEach(function(d, i) { d.style.background = i === current ? "#4f46e5" : "#d1d5db"; d.style.transform = i === current ? "scale(1.2)" : "scale(1)"; }); } imgs.forEach(function(_, i) { var dot = document.createElement("span"); dot.style.cssText = "width:8px; height:8px; border-radius:50%; background:#d1d5db; cursor:pointer; transition:all 0.2s ease; display:inline-block;"; dot.addEventListener("click", function() { goTo(i); }); dots.push(dot); dotsWrap.appendChild(dot); }); /* Prev / Next arrows */ function makeArrow(label, dir) { var btn = document.createElement("button"); btn.type = "button"; btn.innerHTML = dir === -1 ? "←" : "→"; btn.style.cssText = "position:absolute; top:50%; transform:translateY(-50%); " + (dir === -1 ? "left:10px;" : "right:10px;") + "background:rgba(255,255,255,0.85); border:none; border-radius:50%; width:32px; height:32px; font-size:16px; cursor:pointer; box-shadow:0 2px 6px rgba(0,0,0,0.15); z-index:2; display:flex; align-items:center; justify-content:center; transition:background 0.2s;"; btn.addEventListener("click", function() { goTo(current + dir); }); btn.addEventListener("mouseenter", function() { btn.style.background = "#ffffff"; }); btn.addEventListener("mouseleave", function() { btn.style.background = "rgba(255,255,255,0.85)"; }); return btn; } sliderWrap.appendChild(makeArrow("prev", -1)); sliderWrap.appendChild(makeArrow("next", 1)); descDiv.appendChild(sliderWrap); descDiv.appendChild(dotsWrap); goTo(0); /* Auto-advance every 4s */ setInterval(function() { goTo(current + 1); }, 4000); });
//
